-- MySQL 8.4 audit schema. Creates missing tables and preserves existing records.
-- Run only against the separate MySQL 8.4 server.
CREATE DATABASE IF NOT EXISTS `ecpay_audit` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.post_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL,status VARCHAR(10) NOT NULL,reason VARCHAR(255) NOT NULL,database_name VARCHAR(128) NOT NULL,office VARCHAR(80) NOT NULL,account_number VARCHAR(80) NOT NULL,consumer_name VARCHAR(255) NOT NULL,bill_month CHAR(4) NOT NULL,amount DECIMAL(15,2) NOT NULL,date_paid DATE NOT NULL,bill_count INT NOT NULL DEFAULT 0,updated_count INT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uq_ecpay_batch_row(batch_id,account_number,bill_month,amount,date_paid),KEY idx_ecpay_created(created_at),KEY idx_ecpay_account(account_number),KEY idx_ecpay_status(status)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.post_log_v2 (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,batch_row INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL,status VARCHAR(10) NOT NULL,reason VARCHAR(255) NOT NULL,database_name VARCHAR(128) NOT NULL,office VARCHAR(80) NOT NULL,account_number VARCHAR(80) NOT NULL,consumer_name VARCHAR(255) NOT NULL,bill_month CHAR(4) NOT NULL,amount DECIMAL(15,2) NOT NULL,date_paid DATE NOT NULL,bill_count INT NOT NULL DEFAULT 0,updated_count INT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uq_ecpay_batch_row_v2(batch_id,batch_row),KEY idx_ecpay_created_v2(created_at),KEY idx_ecpay_account_v2(account_number),KEY idx_ecpay_status_v2(status)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.post_log_v3 (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,batch_row INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL,status VARCHAR(10) NOT NULL,reason VARCHAR(255) NOT NULL,database_name VARCHAR(128) NOT NULL,office VARCHAR(80) NOT NULL,account_number VARCHAR(80) NOT NULL,consumer_name VARCHAR(255) NOT NULL,bill_month CHAR(4) NOT NULL,amount DECIMAL(15,2) NOT NULL,source_date_paid DATE NULL,date_paid DATE NOT NULL,source_reference VARCHAR(120) NOT NULL DEFAULT '',bill_count INT NOT NULL DEFAULT 0,updated_count INT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uq_ecpay_batch_row_v3(batch_id,batch_row),KEY idx_ecpay_created_v3(created_at),KEY idx_ecpay_account_v3(account_number),KEY idx_ecpay_status_v3(status)) ENGINE=InnoDB;

INSERT IGNORE INTO `ecpay_audit`.post_log_v3(batch_id,batch_row,created_at,status,reason,database_name,office,account_number,consumer_name,bill_month,amount,source_date_paid,date_paid,source_reference,bill_count,updated_count) SELECT batch_id,batch_row,created_at,status,reason,database_name,office,account_number,consumer_name,bill_month,amount,NULL,date_paid,'',bill_count,updated_count FROM `ecpay_audit`.post_log_v2;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.reset_state (id TINYINT UNSIGNED NOT NULL PRIMARY KEY,reset_at DATETIME(3) NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.query_builder_audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,generated_at DATETIME(3) NOT NULL,database_scope VARCHAR(255) NOT NULL,bill_month CHAR(4) NOT NULL,current_date_paid DATE NULL,current_or VARCHAR(80) NOT NULL DEFAULT '',current_collector_code VARCHAR(80) NOT NULL DEFAULT '',new_date_paid DATE NULL,new_or VARCHAR(80) NOT NULL DEFAULT '',new_collector_code VARCHAR(80) NOT NULL DEFAULT '',status VARCHAR(40) NOT NULL,query_text LONGTEXT NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_query_builder_batch(batch_id),KEY idx_query_builder_generated(generated_at),KEY idx_query_builder_month(bill_month)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.query_builder_execution_audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,executed_at DATETIME(3) NOT NULL,status VARCHAR(20) NOT NULL,database_scope VARCHAR(255) NOT NULL,rows_changed INT NOT NULL DEFAULT 0,result_json LONGTEXT NOT NULL,error_message VARCHAR(1000) NOT NULL DEFAULT '',PRIMARY KEY(id),KEY idx_query_execution_batch(batch_id),KEY idx_query_execution_time(executed_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `ecpay_audit`.query_builder_execution_detail (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,batch_id VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL,database_name VARCHAR(128) NOT NULL,office VARCHAR(80) NOT NULL,bill_entry BIGINT NOT NULL,account_number VARCHAR(80) NOT NULL,bill_month CHAR(4) NOT NULL,old_or_collection VARCHAR(80) NOT NULL DEFAULT '',new_or_collection VARCHAR(80) NOT NULL DEFAULT '',old_date_paid DATE NULL,new_date_paid DATE NULL,old_collector_code VARCHAR(80) NOT NULL DEFAULT '',new_collector_code VARCHAR(80) NOT NULL DEFAULT '',created_at DATETIME(3) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_query_execution_detail(batch_id,database_name,bill_entry),KEY idx_query_execution_account(account_number),KEY idx_query_execution_detail_status(status)) ENGINE=InnoDB;

